import React, { useCallback, useState } from 'react';
import { View, FlatList, Image, TouchableOpacity, ActivityIndicator } from 'react-native';
import tw from 'twrnc';
import axios from 'axios';
import { useThemeColor } from '@/hooks/useThemeColor';
import { ThemedView } from '@/components/ThemedView';
import { ThemedText } from '@/components/ThemedText';
import { useRouter } from 'expo-router';
import Constants from 'expo-constants';
import * as SecureStore from 'expo-secure-store';
import { LinearGradient } from 'expo-linear-gradient';
import { useFocusEffect } from '@react-navigation/native';

// ✅ Memoized BookItem for performance
const BookItem = React.memo(({ item, onPress, textColor, secondaryColor }) => (
  <TouchableOpacity
    style={tw`flex-row items-center bg-white p-4 rounded-lg mb-4 shadow-md`}
    onPress={() => onPress(item._id)}
  >
    <Image source={{ uri: item.bookCover }} style={tw`w-16 h-20 rounded-md`} />
    <View style={tw`ml-4 flex-1`}>
      <ThemedText type="subtitle" style={{ color: textColor }}>
        {item.bookName}
      </ThemedText>
      <ThemedText style={{ color: secondaryColor }} type="link">
        by {item.bookAuthor}
      </ThemedText>
    </View>
  </TouchableOpacity>
));

export default function TopChart() {
  const [books, setBooks] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  const router = useRouter();
  const disc = require('../../assets/images/disc.png');
  const backgroundColor = useThemeColor({}, 'background');
  const secondaryColor = useThemeColor({}, 'secondary');
  const textColor = '#070c70';
  const apiUrl = Constants.expoConfig?.extra?.API_BASE_URL;

  // ✅ Properly wrapped useFocusEffect
  useFocusEffect(
    useCallback(() => {
      const fetchBooks = async () => {
        try {
          setLoading(true);
          setError(null);

          const token = await SecureStore.getItemAsync('authToken');
          if (!token) throw new Error('No authentication token found');

          const response = await axios.get(`${apiUrl}/topChart`, {
            headers: {
              Authorization: `Bearer ${token}`,
              'Content-Type': 'application/json',
            },
          });

          const booksData = Array.isArray(response.data?.books) ? response.data.books : [];
          setBooks(booksData);
        } catch (err) {
          setError(err?.message || 'Failed to fetch books');
        } finally {
          setLoading(false);
        }
      };

      fetchBooks();
    }, [apiUrl])
  );

  if (loading) {
    return (
      <ThemedView style={[tw`flex-1 items-center justify-center`, { backgroundColor }]}>
        <ActivityIndicator size="large" color="#ff1493" />
        <ThemedText style={{ color: textColor, marginTop: 10 }}>
          Loading topchart...
        </ThemedText>
      </ThemedView>
    );
  }

  if (error) {
    return (
      <ThemedView style={[tw`flex-1 items-center justify-center`, { backgroundColor }]}>
        <ThemedText style={{ color: textColor }}>Error: {error}</ThemedText>
      </ThemedView>
    );
  }

  return (
    <ThemedView style={tw`flex-1`}>
      <LinearGradient colors={['#070c70', '#ff1493']} style={tw`p-5 rounded-b-xl`}>
        <ThemedText type="title" style={[{ color: 'white' }, tw`pt-9`]}>
          Top Chart
        </ThemedText>
        <View style={tw`flex-row space-x-2 mx-3 mt-2`}>
          <Image source={disc} style={tw`h-25 w-25`} resizeMode="contain" />
          <ThemedText
            style={[tw`text-xl pl-3 pt-5`, { fontStyle: 'italic', color: 'white' }]}
          >
            Listen to the most rated audiobooks right now!
          </ThemedText>
        </View>
      </LinearGradient>

      <FlatList
        data={books}
        keyExtractor={(item) => item._id.toString()}
        showsVerticalScrollIndicator={false}
        keyboardShouldPersistTaps="handled"
        contentContainerStyle={tw`px-6 py-6`}
        renderItem={({ item }) => (
          <BookItem
            item={item}
            onPress={(id) => router.push(`/book-details/${id}`)}
            textColor={textColor}
            secondaryColor={secondaryColor}
          />
        )}
        // ✅ Performance tweaks
        initialNumToRender={10}
        maxToRenderPerBatch={10}
        windowSize={5}
        removeClippedSubviews
        getItemLayout={(data, index) => ({
          length: 96, // estimated row height (item + margins)
          offset: 96 * index,
          index,
        })}
      />
    </ThemedView>
  );
}
